3: /**
4:  * Verifies `t=<unix_sec>,v1=<hex_hmac_sha256>` webhook signatures against raw body bytes
5:  * and rejects timestamps older (or further ahead) than 5 minutes.
6:  */
7: export function verifyWebhookSignature(
8:   header: string | undefined,
9:   rawBody: Buffer,
10:   secret: string
11: ): boolean {
12:   if (!header || typeof header !== 'string') return false;
13:   let tStr = '';
14:   let v1 = '';
15:   for (const part of header.split(',')) {
16:     const eq = part.indexOf('=');
17:     if (eq <= 0) continue;
18:     const k = part.slice(0, eq).trim();
19:     const v = part.slice(eq + 1).trim();
20:     if (k === 't') tStr = v;
21:     else if (k === 'v1') v1 = v;
22:   }
23:   if (!tStr || !v1 || !/^\d+$/.test(tStr) || !/^[0-9a-f]+$/i.test(v1)) return false;
24: 
25:   const t = Number(tStr);
26:   const nowSec = Math.floor(Date.now() / 1000);
27:   if (Math.abs(nowSec - t) > 300) return false;
28: 
29:   const expected = crypto
30:     .createHmac('sha256', secret)
31:     .update(`${tStr}.`)
32:     .update(rawBody)
33:     .digest('hex');
34: 
35:   const a = Buffer.from(v1.toLowerCase(), 'utf8');
36:   const b = Buffer.from(expected.toLowerCase(), 'utf8');
37:   return a.length === b.length && crypto.timingSafeEqual(a, b);
38: }

