27:  * Persists a workspace event with a durable MongoDB sequence number BEFORE publishing
28:  * to Redis Pub/Sub. Serialized per workspace so live WebSocket frames arrive in strictly
29:  * increasing `seq` order, and idempotent when `dedupeKey` is supplied.
30:  */
31: export async function emitWorkspaceEvent(
32:   workspace: string,
33:   type: string,
34:   fields: Record<string, unknown>,
35:   dedupeKey?: string
36: ): Promise<Record<string, unknown>> {
37:   return withWorkspaceEmitLock(workspace, async () => {
