1: // Client-side AES-GCM encryption for private agent notes with Associated Data (AAD).
2: // The server only ever sees base64(iv) and base64(ciphertext) and cannot swap notes
3: // across conversations or authors without failing GCM authentication.
4: 
5: const STORAGE_PREFIX = 'sb_note_key_';
6: 
7: function toBase64(buf: ArrayBuffer | Uint8Array): string {
8:   const bytes = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
9:   let bin = '';
10:   for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
11:   return btoa(bin);
12: }
13: 
14: function fromBase64(b64: string): Uint8Array<ArrayBuffer> {
15:   const bin = atob(b64);
16:   const buf = new ArrayBuffer(bin.length);
17:   const bytes = new Uint8Array(buf);
18:   for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
19:   return bytes;
20: }
21: 
22: function buildAad(workspace: string, contact: string, authorSub: string): Uint8Array<ArrayBuffer> {
23:   const encoded = new TextEncoder().encode(`${workspace}|${contact}|${authorSub}`);
24:   const buf = new ArrayBuffer(encoded.byteLength);
25:   new Uint8Array(buf).set(encoded);
26:   return new Uint8Array(buf);
27: }
28: 
29: export async function getOrCreateWorkspaceKey(workspace: string): Promise<CryptoKey> {
30:   const stored = localStorage.getItem(STORAGE_PREFIX + workspace);
31:   if (stored) {
32:     return crypto.subtle.importKey('raw', fromBase64(stored), 'AES-GCM', false, ['encrypt', 'decrypt']);
33:   }
34:   const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, true, ['encrypt', 'decrypt']);
35:   const raw = await crypto.subtle.exportKey('raw', key);
36:   localStorage.setItem(STORAGE_PREFIX + workspace, toBase64(raw));
37:   return key;
38: }
39: 
40: export function exportWorkspaceKeyString(workspace: string): string {
41:   return localStorage.getItem(STORAGE_PREFIX + workspace) || '';
42: }
43: 
44: export function importWorkspaceKeyString(workspace: string, b64: string): void {
45:   localStorage.setItem(STORAGE_PREFIX + workspace, b64.trim());
46: }
47: 
48: export async function encryptNote(
49:   workspace: string,
50:   contact: string,
51:   authorSub: string,
52:   plaintext: string
53: ): Promise<{ ciphertext: string; iv: string }> {
54:   const key = await getOrCreateWorkspaceKey(workspace);
55:   const iv = crypto.getRandomValues(new Uint8Array(12));
56:   const encoded = new TextEncoder().encode(plaintext);
57:   const cipher = await crypto.subtle.encrypt(
58:     { name: 'AES-GCM', iv, additionalData: buildAad(workspace, contact, authorSub) },
59:     key,
60:     encoded
61:   );
62:   return { ciphertext: toBase64(cipher), iv: toBase64(iv) };
63: }
64: 
65: export async function decryptNote(
66:   workspace: string,
67:   contact: string,
68:   authorSub: string,
69:   ciphertext: string,
70:   iv: string
71: ): Promise<string> {
72:   try {
73:     const key = await getOrCreateWorkspaceKey(workspace);
74:     const plain = await crypto.subtle.decrypt(
75:       { name: 'AES-GCM', iv: fromBase64(iv), additionalData: buildAad(workspace, contact, authorSub) },
76:       key,
77:       fromBase64(ciphertext)
78:     );
79:     return new TextDecoder().decode(plain);
80:   } catch {
81:     return '[Unable to decrypt — missing key or tampered context]';
82:   }
83: }

